const item = $input.first();
const chatId = item.json.chat_id;
const isPDF = item.json.is_pdf === true;

// Get binary data
if (!item.binary) {
    return {
        json: {
            ...item.json,
            error: true,
            error_message: 'No binary data'
        }
    };
}

const binaryKeys = Object.keys(item.binary);

// Find the image/file key
let fileKey = null;
const photoKeys = binaryKeys.filter(k => k.startsWith('photo'));

if (photoKeys.length > 0) {
    // Get highest quality photo
    fileKey = photoKeys.sort().reverse()[0];
} else if (binaryKeys.includes('data')) {
    fileKey = 'data';
} else if (binaryKeys.length > 0) {
    fileKey = binaryKeys[0];
}

if (!fileKey) {
    return {
        json: {
            ...item.json,
            error: true,
            error_message: 'No file data found'
        }
    };
}

const binaryData = item.binary[fileKey];

// ✅ SOFTER VALIDATION - Just check if binaryData exists
if (!binaryData) {
    return {
        json: {
            ...item.json,
            error: true,
            error_message: 'Invalid binary data'
        }
    };
}

// Get filename and mime type
let originalFilename = binaryData.fileName || `receipt_${Date.now()}`;
let originalMimeType = binaryData.mimeType;

// Add extension if missing
if (!originalFilename.includes('.')) {
    if (isPDF) {
        originalFilename += '.pdf';
    } else if (originalMimeType?.includes('jpeg') || originalMimeType?.includes('jpg')) {
        originalFilename += '.jpg';
    } else if (originalMimeType?.includes('png')) {
        originalFilename += '.png';
    } else if (originalMimeType?.includes('heic') || originalMimeType?.includes('heif')) {
        originalFilename += '.heic';
    } else {
        originalFilename += '.jpg'; // default
    }
}

return {
    json: {
        ...item.json,
        file_key: fileKey,
        original_filename: originalFilename,
        original_mime_type: originalMimeType,
        file_type: isPDF ? 'pdf' : 'image',
        is_image: true
    },
    binary: item.binary
};

