function matchVendorDatabase(vendorName) {
  if (!vendorName || vendorName === 'XXX') return null;

  const cleanVendor = vendorName.toUpperCase().replace(/[^A-Z0-9\s]/g, '');

  for (const [category, vendors] of Object.entries(VENDOR_DATABASE)) {
    for (const knownVendor of vendors) {
      if (cleanVendor.includes(knownVendor) || knownVendor.includes(cleanVendor)) {
        return { category, vendor: knownVendor, confidence: 95 };
      }
    }
  }

  return null;
}

function detectTransportSubcategory(ocrText, vendorMatch, amount) {
  const text = ocrText.toUpperCase();

  const fuelKeywords = ['PETROL', 'DIESEL', 'UNLEADED', 'PREMIUM', 'FUEL', 'GAS', 'LITERS', 'LITRES', 'GALLONS'];
  const hasFuelKeyword = fuelKeywords.some(kw => text.includes(kw));

  if (vendorMatch?.category === 'fuel' || hasFuelKeyword) {
    return { subcategory: 'Fuel/Gas', confidence: 95 };
  }

  const flightKeywords = ['FLIGHT', 'BOARDING', 'GATE', 'SEAT', 'BAGGAGE', 'CHECK-IN', 'TERMINAL'];
  const hasFlightKeyword = flightKeywords.some(kw => text.includes(kw));

  if (vendorMatch?.category === 'airlines' || hasFlightKeyword) {
    return { subcategory: 'Flight', confidence: 95 };
  }

  if (vendorMatch?.category === 'ride_sharing') {
    return { subcategory: 'Ride-Sharing', confidence: 99 };
  }

  const transitKeywords = ['TICKET', 'FARE', 'STATION', 'METRO', 'SUBWAY', 'BUS', 'TRAIN', 'RAIL'];
  const hasTransitKeyword = transitKeywords.some(kw => text.includes(kw));

  if (vendorMatch?.category === 'public_transit' || hasTransitKeyword) {
    const numAmount = parseFloat(String(amount).replace(/[,]/g, ''));

    if (numAmount < 10) return { subcategory: 'Bus/Metro', confidence: 90 };
    if (numAmount < 50) return { subcategory: 'Train/Rail', confidence: 85 };
    return { subcategory: 'Public Transit', confidence: 80 };
  }

  const parkingKeywords = ['PARKING', 'PARK', 'CARPARK', 'VALET'];
  if (parkingKeywords.some(kw => text.includes(kw))) {
    return { subcategory: 'Parking', confidence: 95 };
  }

  const tollKeywords = ['TOLL', 'ERP', 'EXPRESSWAY', 'HIGHWAY'];
  if (tollKeywords.some(kw => text.includes(kw))) {
    return { subcategory: 'Toll/ERP', confidence: 95 };
  }

  const taxiKeywords = ['TAXI', 'CAB', 'COMFORT', 'CITYCAB'];
  if (taxiKeywords.some(kw => text.includes(kw))) {
    return { subcategory: 'Taxi', confidence: 90 };
  }

  return { subcategory: 'General', confidence: 70 };
}

function inferMealCategory(vendorMatch, time, ocrText) {
  if (vendorMatch?.category === 'convenience') {
    return { category: 'Meals - Snacks', confidence: 95, reason: 'Convenience store' };
  }

  if (vendorMatch?.category === 'supermarket') {
    return { category: 'Groceries', confidence: 95, reason: 'Supermarket purchase' };
  }

  if (vendorMatch?.category === 'coffee_tea') {
    const mealKeywords = ['SANDWICH', 'BURGER', 'WRAP', 'SALAD', 'PASTA', 'RICE', 'NOODLE', 'BOWL'];
    const hasMeal = mealKeywords.some(kw => ocrText.toUpperCase().includes(kw));

    if (hasMeal && time && time !== 'XXX') {
      return inferMealFromTime(time, 'Coffee chain with meal items');
    }

    return { category: 'Meals - Drinks', confidence: 95, reason: 'Coffee/tea chain' };
  }

  if (time && time !== 'XXX') {
    return inferMealFromTime(time, 'Time-based inference');
  }

  const breakfastKeywords = ['BREAKFAST', 'MORNING', 'TOAST', 'EGG', 'BACON'];
  const lunchKeywords = ['LUNCH', 'NOON'];
  const dinnerKeywords = ['DINNER', 'EVENING', 'SUPPER'];

  const textUpper = ocrText.toUpperCase();

  if (breakfastKeywords.some(kw => textUpper.includes(kw))) {
    return { category: 'Meals - Breakfast', confidence: 80, reason: 'Keyword detection' };
  }
  if (lunchKeywords.some(kw => textUpper.includes(kw))) {
    return { category: 'Meals - Lunch', confidence: 80, reason: 'Keyword detection' };
  }
  if (dinnerKeywords.some(kw => textUpper.includes(kw))) {
    return { category: 'Meals - Dinner', confidence: 80, reason: 'Keyword detection' };
  }

  return { category: 'Meals - General', confidence: 60, reason: 'Default fallback' };
}

function inferMealFromTime(time, reason) {
  const [hour] = time.split(':').map(Number);

  if (hour >= 0 && hour < 5) return { category: 'Meals - Supper', confidence: 90, reason };
  if (hour >= 5 && hour < 11) return { category: 'Meals - Breakfast', confidence: 90, reason };
  if (hour >= 11 && hour < 15) return { category: 'Meals - Lunch', confidence: 90, reason };
  if (hour >= 15 && hour < 23) return { category: 'Meals - Dinner', confidence: 90, reason };
  if (hour === 23) return { category: 'Meals - Supper', confidence: 90, reason };

  return { category: 'Meals - General', confidence: 70, reason: 'Invalid time' };
}

