function extractOCRConfidence(ocrData) {
  const confidenceScores = {
    overall: 0,
    words: []
  };

  try {
    if (ocrData.fullTextAnnotation && ocrData.fullTextAnnotation.pages) {
      const pages = ocrData.fullTextAnnotation.pages;
      let totalWords = 0;
      let totalConfidence = 0;

      pages.forEach(page => {
        if (page.blocks) {
          page.blocks.forEach(block => {
            if (block.confidence) {
              totalConfidence += block.confidence;
              totalWords++;
            }

            if (block.paragraphs) {
              block.paragraphs.forEach(paragraph => {
                if (paragraph.words) {
                  paragraph.words.forEach(word => {
                    if (word.confidence) {
                      totalConfidence += word.confidence;
                      totalWords++;

                      const wordText = word.symbols
                        ? word.symbols.map(s => s.text).join('')
                        : '';

                      confidenceScores.words.push({
                        text: wordText,
                        confidence: Math.round(word.confidence * 100)
                      });
                    }
                  });
                }
              });
            }
          });
        }
      });

      if (totalWords > 0) {
        confidenceScores.overall = Math.round((totalConfidence / totalWords) * 100);
      }
    }

    if (confidenceScores.overall === 0 && ocrData.textAnnotations && ocrData.textAnnotations.length > 1) {
      let totalConfidence = 0;
      let count = 0;

      for (let i = 1; i < Math.min(ocrData.textAnnotations.length, 100); i++) {
        const annotation = ocrData.textAnnotations[i];
        if (annotation.confidence !== undefined) {
          totalConfidence += annotation.confidence;
          count++;
        }
      }

      if (count > 0) {
        confidenceScores.overall = Math.round((totalConfidence / count) * 100);
      } else {
        confidenceScores.overall = 85;
      }
    }

    if (confidenceScores.overall === 0) {

      if (ocrData.textAnnotations && ocrData.textAnnotations[0]) {
        const textLength = ocrData.textAnnotations[0].description.length;

        if (textLength > 100) {
          confidenceScores.overall = 85;
        } else if (textLength > 50) {
          confidenceScores.overall = 70;
        } else {
          confidenceScores.overall = 60;
        }

      } else {
        confidenceScores.overall = 50;
      }
    }

  } catch (error) {
    confidenceScores.overall = 75;
  }

  return confidenceScores;
}

const ocrConfidenceData = extractOCRConfidence(ocrData);

function getSingaporeTimestamps() {
  const now = new Date();
  const singaporeTime = new Date(now.getTime() + (8 * 60 * 60 * 1000));

  const day = String(singaporeTime.getDate()).padStart(2, '0');
  const month = singaporeTime.toLocaleString('en-GB', { month: 'short', timeZone: 'Asia/Singapore' });
  const year = singaporeTime.getFullYear();
  const hour = String(singaporeTime.getHours()).padStart(2, '0');
  const minute = String(singaporeTime.getMinutes()).padStart(2, '0');

  return {
    date: `${day}-${month}-${year}`,
    time: `${hour}:${minute}`,
    datetime: `${day}-${month}-${year} ${hour}:${minute}`,
    timezone: 'GMT+8',
    timestamp: now.getTime(),
    iso_string: now.toISOString()
  };
}

const singaporeTimestamps = getSingaporeTimestamps();

function inferCambodiaFromDualCurrency(ocrText) {
  const hasUSD = /\$\s*[\d,]+\.?\d*|\bUSD\b/i.test(ocrText);
  const hasKHR = /\bKHR\b|\bRiel\b/i.test(ocrText);
  const hasLargeNumber = /[\d,]{5,}/.test(ocrText);

  const hasKhmerScript = /[\u1780-\u17FF]/.test(ocrText);
  const hasCambodiaPhone = /\+855|\(855\)|855[\s-]?\d/.test(ocrText);
  const hasPhnomPenh = /phnom\s*penh|ភ្នំពេញ/i.test(ocrText);

  const isDualCurrency = hasUSD && (hasKHR || hasLargeNumber);
  const hasCambodiaIndicators = hasKhmerScript || hasCambodiaPhone || hasPhnomPenh;

  if (isDualCurrency || hasCambodiaIndicators) {
    return true;
  }

  return false;
}

const isCambodiaReceipt = inferCambodiaFromDualCurrency(ocrText);

