function shuffleArray(array) {
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

const shuffledProviders = shuffleArray(API_PROVIDERS);
const primaryProvider = shuffledProviders[0];
const fallbackProviders = shuffledProviders.slice(1);


const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
const MAX_RETRIES = 2;
const BASE_DELAY = 800;

const attemptedProviders = [];
const failedProviders = [];

function formatCurrencyByCountry(amount, currency) {
  if (!amount || amount === 'XXX') return amount;

  const cleanAmount = String(amount).replace(/[,\s]/g, '');
  const numAmount = parseFloat(cleanAmount);

  if (isNaN(numAmount)) return amount;

  const zeroDecimalCurrencies = ['IDR', 'KHR', 'VND', 'JPY', 'KRW', 'CLP', 'PYG'];

  if (zeroDecimalCurrencies.includes(currency)) {
    const wholeNumber = Math.round(numAmount);
    const formatted = wholeNumber.toLocaleString('en-US');
    return formatted;
  } else {
    const formatted = numAmount.toLocaleString('en-US', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
    return formatted;
  }
}

function analyzeConfidence(data, ocrConfidence) {
  const confidenceThreshold = 75;
  const lowConfidenceFields = [];

  const fieldConfidenceMap = {
    date: data.date_confidence || 0,
    time: data.time_confidence || 0,
    vendor: data.vendor_confidence || 0,
    location: data.location_confidence || 0,
    total_amount: data.amount_confidence || 0,
    currency: data.currency_confidence || 0,
    tax_amount: data.tax_confidence || 0,
    category: data.category_confidence || 0
  };

  Object.keys(fieldConfidenceMap).forEach(field => {
    const confidence = fieldConfidenceMap[field];
    const fieldValue = data[field];

    if (confidence < confidenceThreshold && fieldValue === 'XXX') {
      lowConfidenceFields.push({
        field: field,
        confidence: confidence,
        value: fieldValue,
        reason: confidence < 50 ? 'Very uncertain' : 'Needs verification'
      });
    }
  });

  if (!data.overall_confidence) {
    const confidenceValues = Object.values(fieldConfidenceMap);
    const totalConfidence = confidenceValues.reduce((sum, conf) => sum + conf, 0);
    data.overall_confidence = Math.round(totalConfidence / confidenceValues.length);
  }

  const combinedConfidence = Math.round(
    (data.overall_confidence * 0.7) + (ocrConfidence * 0.3)
  );

  const hasXXXFields = Object.values(data).some(value => value === 'XXX');
  const needsManualReview = hasXXXFields && (
    combinedConfidence < confidenceThreshold || 
    lowConfidenceFields.length > 0
  );

  return {
    overall: data.overall_confidence,
    combined: combinedConfidence,
    ocr_quality: ocrConfidence,
    threshold: confidenceThreshold,
    needs_manual_review: needsManualReview,
    low_confidence_fields: lowConfidenceFields,
    field_scores: fieldConfidenceMap
  };
}

async function processWithProvider(provider, prompt, attempt = 1) {
  attemptedProviders.push(provider.name);

  try {
    const startTime = Date.now();
    const config = provider.config(prompt);
    const response = await this.helpers.httpRequest(config);
    const elapsed = ((Date.now() - startTime) / 1000).toFixed(2);

    let rawContent;
    if (provider.name.includes('Gemini')) {
      rawContent = response.candidates?.[0]?.content?.parts?.[0]?.text;
    } else if (provider.name.includes('Anthropic')) {
      rawContent = response.content?.[0]?.text;
    } else {
      rawContent = response.choices?.[0]?.message?.content;
    }

    if (!rawContent) throw new Error('Empty response');

    const cleanContent = rawContent.replace(/```json\n?|```\n?/g, '').trim();
    const jsonMatch = cleanContent.match(/\{[\s\S]*\}/) || [cleanContent];
    const data = JSON.parse(jsonMatch[0]);

    const required = ['date', 'vendor', 'total_amount', 'currency'];
    const missing = required.filter(field => !data[field]);
    if (missing.length > 0) throw new Error(`Missing: ${missing.join(', ')}`);


    if (data.location === 'XXX' && data.currency !== 'XXX') {
      data.currency = 'XXX';
      data.currency_confidence = 0;
      data.comment = (data.comment || '') + ' Location unknown, currency requires verification.';
    }

    const originalAmount = data.total_amount;
    const originalTax = data.tax_amount;

    if (data.currency !== 'XXX') {
      data.total_amount = formatCurrencyByCountry(data.total_amount, data.currency);
      data.tax_amount = formatCurrencyByCountry(data.tax_amount, data.currency);

    } else {
      if (data.total_amount && data.total_amount !== 'XXX') {
        data.total_amount = parseFloat(data.total_amount).toFixed(2);
      } else {
        data.total_amount = '0.00';
      }

      if (data.tax_amount && data.tax_amount !== 'XXX') {
        data.tax_amount = parseFloat(data.tax_amount).toFixed(2);
      } else {
        data.tax_amount = '0.00';
      }
    }

    const numTotal = parseFloat(data.total_amount);
    const numTax = parseFloat(data.tax_amount);
    if (!isNaN(numTotal) && !isNaN(numTax) && numTax > numTotal) {
      data.tax_amount = '0';
    }

    const validCategories = [
      'Meals - Breakfast', 'Meals - Lunch', 'Meals - Dinner', 'Meals - Supper',
      'Meals - Snacks', 'Meals - Drinks', 'Meals - General',
      'Groceries',
      'Transportation - Fuel/Gas', 'Transportation - Flight', 'Transportation - Ride-Sharing',
      'Transportation - Public Transit', 'Transportation - Taxi', 'Transportation - Parking',
      'Transportation - General',
      'Accommodation', 'Office Supplies', 'Software/Subscriptions',
      'Entertainment', 'Medical', 'Miscellaneous'
    ];

    if (!validCategories.includes(data.category)) {
      data.category = 'Miscellaneous';
    }

    const confidenceAnalysis = analyzeConfidence(data, ocrConfidenceData.overall);


    delete data.date_confidence;
    delete data.time_confidence;
    delete data.vendor_confidence;
    delete data.location_confidence;
    delete data.amount_confidence;
    delete data.currency_confidence;
    delete data.tax_confidence;
    delete data.category_confidence;

    const relevantFields = ['date', 'time', 'vendor', 'location', 'total_amount', 'currency', 'tax_amount', 'category'];
    const xxxFields = relevantFields.filter(field => data[field] === 'XXX');


    return {
      success: true,
      data: {
        ...data,
        chat_id: chatId,
        status: 'success',
        parsed_by: provider.name,
        provider_tier: provider.tier,
        parsing_time: parseFloat(elapsed),
        needs_review: confidenceAnalysis.needs_manual_review,
        review_fields: xxxFields,
        confidence_scores: confidenceAnalysis,
        submission_date: singaporeTimestamps.date,
        submission_time: singaporeTimestamps.time,
        submission_datetime: singaporeTimestamps.datetime,
        submission_timezone: singaporeTimestamps.timezone,
        submission_timestamp: singaporeTimestamps.iso_string,
        attempted_providers: attemptedProviders
      }
    };

  } catch (error) {
    const requestConfig = provider.config(prompt);

    const errorDetails = {
      message: error.message,
      statusCode: error.statusCode,
      code: error.code,
      stack: error.stack,
      responseBody: error.response?.body || 'No response body',
      responseHeaders: error.response?.headers || 'No response headers',
      requestConfig: {
        url: requestConfig.url,
        method: requestConfig.method,
        headers: requestConfig.headers ? Object.keys(requestConfig.headers) : 'No headers',
        hasBody: !!requestConfig.body
      }
    };


    failedProviders.push({
      provider: provider.name,
      attempt: attempt,
      error: `Status ${error.statusCode}: ${error.message}`,
      fullError: errorDetails
    });

    if (attempt < MAX_RETRIES) {
      const delay = error.statusCode === 429 ? BASE_DELAY * Math.pow(2, attempt) : BASE_DELAY;
      await sleep(delay);
      return processWithProvider.call(this, provider, prompt, attempt + 1);
    }

    return { success: false };
  }
}

let result;

result = await processWithProvider.call(this, primaryProvider, PROMPT);

if (!result.success) {

  for (const fallbackProvider of fallbackProviders) {
    result = await processWithProvider.call(this, fallbackProvider, PROMPT);

    if (result.success) {
      break;
    }
  }
}

// ==================== POST-PROCESSING: CATEGORY ENHANCEMENT ====================
if (result.success) {
  const data = result.data;


  // Fix ambiguous meal categories
  if (data.category && (data.category.includes('XXX') || data.category === 'Meals - General')) {
    const inferredMeal = inferMealCategory(vendorMatch, data.time, ocrText);

    data.category = inferredMeal.category;
    if (inferredMeal.confidence > data.overall_confidence) {
      data.overall_confidence = inferredMeal.confidence;
    }
  }

  // Enhance transportation subcategories
  if (data.category && data.category.startsWith('Transportation')) {
    const transportDetail = detectTransportSubcategory(ocrText, vendorMatch, data.total_amount);

    if (transportDetail.subcategory !== 'General') {
      const enhancedCategory = `Transportation - ${transportDetail.subcategory}`;

      data.category = enhancedCategory;
      if (transportDetail.confidence > data.overall_confidence) {
        data.overall_confidence = transportDetail.confidence;
      }
    }
  }

  // Add vendor classification to comment
  if (vendorMatch && data.comment) {
    data.comment = `${vendorMatch.vendor} (${vendorMatch.category}). ${data.comment}`;
  }


  return [{ json: data }];
} else {
  return [{ 
    json: { 
      error: true, 
      message: `All ${API_PROVIDERS.length} providers failed`, 
      chat_id: chatId, 
      status: 'error',
      submission_date: singaporeTimestamps.date,
      submission_time: singaporeTimestamps.time,
      submission_datetime: singaporeTimestamps.datetime,
      submission_timezone: singaporeTimestamps.timezone,
      attempted_providers: attemptedProviders,
      failed_providers: failedProviders
    } 
  }];
}

