function isValidDate(value) {
  const dateRegex1 = /^(\d{2})-([A-Za-z]{3})-(\d{4})$/;
  const dateRegex2 = /^(\d{2})-(\d{2})-(\d{2})$/;

  const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const monthNumbers = {
    'Jan': 0, 'Feb': 1, 'Mar': 2, 'Apr': 3, 'May': 4, 'Jun': 5,
    'Jul': 6, 'Aug': 7, 'Sep': 8, 'Oct': 9, 'Nov': 10, 'Dec': 11
  };
  let day, month, year;
  const match1 = value.match(dateRegex1);
  if (match1) {
    day = parseInt(match1[1], 10);
    month = monthNumbers[match1[2]];
    year = parseInt(match1[3], 10);
  } else {
    const match2 = value.match(dateRegex2);
    if (match2) {
      day = parseInt(match2[1], 10);
      month = parseInt(match2[2], 10) - 1;
      year = parseInt(match2[3], 10) + 2000;
    } else {
      return { valid: false, error: 'Invalid date format. Use DD-MMM-YYYY (15-Nov-2025) or DD-MM-YY (06-07-25)' };
    }
  }
  if (month === undefined || month < 0 || month > 11) {
    return { valid: false, error: 'Invalid month. Month must be between 01-12 or valid 3-letter abbreviation' };
  }
  if (day < 1 || day > 31) {
    return { valid: false, error: 'Invalid day. Day must be between 01-31' };
  }
  if (year < 2000 || year > 2099) {
    return { valid: false, error: 'Invalid year. Year must be between 2000-2099' };
  }
  const daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (month === 1) {
    const isLeapYear = (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
    if (day > (isLeapYear ? 29 : 28)) {
      return { valid: false, error: `Invalid day for February ${year}. Maximum is ${isLeapYear ? 29 : 28} days` };
    }
  } else if (day > daysInMonth[month]) {
    return { valid: false, error: `Invalid day for ${monthNames[month]}. Maximum is ${daysInMonth[month]} days` };
  }
  return { valid: true, day, month, year, monthName: monthNames[month] };
