    'MAD', 'MDL', 'MGA', 'MKD', 'MMK', 'MNT', 'MOP', 'MRU', 'MUR', 'MVR', 'MWK', 'MXN', 'MYR', 'MZN',
    'NAD', 'NGN', 'NIO', 'NOK', 'NPR', 'NZD',
    'OMR',
    'PAB', 'PEN', 'PGK', 'PHP', 'PKR', 'PLN', 'PYG',
    'QAR',
    'RON', 'RSD', 'RUB', 'RWF',
    'SAR', 'SBD', 'SCR', 'SDG', 'SEK', 'SGD', 'SHP', 'SLE', 'SLL', 'SOS', 'SPL', 'SRD', 'STN', 'SYP',
    'SZL',
    'THB', 'TJS', 'TMT', 'TND', 'TOP', 'TRY', 'TTD', 'TVD', 'TWD',
    'TZS',
    'UAH', 'UGX', 'USD', 'UYU', 'UZS',
    'VEF', 'VES', 'VND', 'VUV',
    'WST',
    'XAF', 'XCD', 'XDR', 'XOF', 'XPF',
    'YER',
    'ZAR', 'ZMW', 'ZWD'
  ];

  return validCurrencies.includes(code.toUpperCase());
}
// ========================================
// FIELD-SPECIFIC VALIDATION
// ========================================
switch(fieldToFix) {
  case 'date':
    const dateResult = isValidDate(validatedValue);
    if (!dateResult.valid) {
      isValid = false;
      errorMessage = dateResult.error;
    } else {
      const paddedDay = String(dateResult.day).padStart(2, '0');
      validatedValue = `${paddedDay}-${dateResult.monthName}-${dateResult.year}`;
    }
    break;

  case 'time':
    const timeRegex = /^([0-1][0-9]|2[0-3]):([0-5][0-9])$/;
    if (!timeRegex.test(validatedValue)) {
      isValid = false;
      errorMessage = '❌ Time must be in HH:MM format (e.g., 09:30, 14:45)';
    }
    break;

  case 'vendor':
    if (validatedValue.length < 2) {
      isValid = false;
      errorMessage = '❌ Vendor name must be at least 2 characters long';
    }
    break;

  case 'location':
    if (validatedValue.length < 3) {
      isValid = false;
      errorMessage = '❌ Location must be at least 3 characters (e.g., Kuala Lumpur, Malaysia)';
    }
    break;

  case 'category':
    if (validatedValue.length < 3) {
      isValid = false;
      errorMessage = '❌ Category must be at least 3 characters';
    }
    break;

  case 'total_amount':
  case 'tax_amount':
    const amount = parseFloat(validatedValue);
    if (isNaN(amount) || amount < 0) {
      isValid = false;
      errorMessage = '❌ Amount must be a valid positive number';
    } else {
      validatedValue = amount.toFixed(2);
    }
    break;

  case 'currency':
    const currencyCode = validatedValue.toUpperCase();
    if (!isValidCurrency(currencyCode)) {
      isValid = false;
      errorMessage = '❌ Invalid currency code. Please use ISO 4217 codes (e.g., USD, EUR, MYR, SGD)';
    } else {
      validatedValue = currencyCode;
    }
    break;

  default:
    if (validatedValue.length === 0) {
      isValid = false;
      errorMessage = '❌ Value cannot be empty';
    }
}
if (!isValid) {
  return [{
    json: {
      chat_id: chatId,
      valid: false,
      error_message: errorMessage,
      skip: false,
      bot_token: botToken
    }
  }];
}
// Map field names to column names
const fieldToColumnMap = {
  'date': 'date',
  'time': 'time',
  'vendor': 'vendor',
  'location': 'location',
  'category': 'category',
  'total_amount': 'amount',
  'currency': 'currency',
  'tax_amount': 'tax'
};
const columnToUpdate = fieldToColumnMap[fieldToFix];
const nextIndex = currentIndex + 1;
const allFixed = nextIndex >= reviewFields.length;
return [{
  json: {
    chat_id: chatId,
    valid: true,
    column_to_update: columnToUpdate,
    new_value: validatedValue,
    field_fixed: fieldToFix,
    next_index: nextIndex,
    all_fixed: allFixed,
    pending_data: pendingData,
    record_id: recordId,
    confirmation_message: `✅ ${fieldToFix} updated to: ${validatedValue}`,
    skip: false,
    bot_token: botToken
  }
}];

