const chatId = item.chat_id;
const nextIndex = item.next_index;
const allFixed = item.all_fixed;
const pendingData = item.pending_data;

// ✅ CRITICAL FIX: Extract the record ID
const recordId = pendingData.id;


// Map snake_case column names to PascalCase field names for Google Sheets/PostgreSQL
const columnToPascalCaseMap = {
  'date': 'Date',
  'time': 'Time',
  'vendor': 'Vendor',
  'location': 'Location',
  'amount': 'Amount',
  'currency': 'Currency',
  'tax': 'Tax',
  'category': 'Category',
  'comment': 'Comment'
};

// Get the PascalCase field name
const pascalCaseField = columnToPascalCaseMap[columnToUpdate] || columnToUpdate;

// Get review fields array - keep it intact
const reviewFieldsRaw = pendingData['review_fields'] || pendingData['Review Fields'] || '';

// Create update payload
const updatePayload = {
  'Chat ID': chatId,
  'Current Fix Index': nextIndex,
  'Conversation State': allFixed ? 'awaiting_action' : 'awaiting_field_input',
  'Review Fields': reviewFieldsRaw, // ✅ PRESERVE AS-IS (don't modify the array)
  'Needs Review': !allFixed // Set to false only when all fields are fixed
};

// ONLY update the specific field that was fixed (using PascalCase name)
updatePayload[pascalCaseField] = newValue;

// Preserve all other fields from pending_data
const fieldsToPreserve = [
  'Date', 'Time', 'Vendor', 'Location', 'Currency', 'Amount', 'Tax', 
  'Category', 'Comment', 'Receipt Image URL', 'Drive File ID',
  'Parsed By', 'Parsing Time', 'Provider Tier', 'Confidence Score', 
  'Submission Datetime'
];

fieldsToPreserve.forEach(field => {
  // Map snake_case back to PascalCase for preservation
  const snakeField = field.toLowerCase().replace(/ /g, '_');
  const pendingValue = pendingData[snakeField] || pendingData[field];

  if (field !== pascalCaseField && pendingValue !== undefined) {
    updatePayload[field] = pendingValue;
  }
});


return [{
  json: {
    id: recordId,  // ✅ ADDED: Pass through the ID for UPSERT
    update_payload: updatePayload,
    chat_id: chatId,
    field_updated: pascalCaseField,
    new_value: newValue,
    all_fixed: allFixed,
    current_fix_index: nextIndex
  ,
    bot_token: botToken}
}];

