const item = $input.first();

// Check if we should skip image optimization (for PDFs)
const skipOptimization = item.json.skip_image_optimization === true;

if (skipOptimization) {
    return {
        json: {
            ...item.json,
            processing_note: 'PDF processed directly - no image optimization'
        },
        binary: item.binary
    };
}

// Regular image processing path
if (!item.binary) {
    throw new Error('No binary data available - check previous node output');
}

const binaryKeys = Object.keys(item.binary);

if (binaryKeys.length === 0) {
    throw new Error('Binary object exists but is empty - no data to process');
}

// Try to find the right binary key
let sourceKey = binaryKeys.find(k => k.includes('ocr_optimized')) 
    || binaryKeys.find(k => k.includes('data'))
    || item.json.optimized_file_key 
    || binaryKeys[0];

if (!sourceKey || !item.binary[sourceKey]) {
    throw new Error('Binary key not found. Available: ' + binaryKeys.join(', '));
}

const binaryData = item.binary[sourceKey];

let base64Image;

try {
    // METHOD 1: Try n8n's helper method (works for n8n 2.0+)
    try {
        const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, sourceKey);

        if (binaryBuffer && binaryBuffer.length > 0) {
            base64Image = binaryBuffer.toString('base64');
        } else {
            throw new Error('getBinaryDataBuffer returned empty buffer');
        }
    } catch (helperError) {
        // METHOD 2: Direct data access
        if (Buffer.isBuffer(binaryData.data)) {
            base64Image = binaryData.data.toString('base64');
        } 
        else if (typeof binaryData.data === 'string') {
            // Check if it's a filesystem reference
            if (binaryData.data.startsWith('filesystem')) {
                throw new Error('Data is filesystem reference but helper method failed. This is a compatibility issue.');
            }

            // Check if already base64
            if (binaryData.data.match(/^[A-Za-z0-9+/]+=*$/)) {
                base64Image = binaryData.data;
            } else {
                // Convert string to base64
                base64Image = Buffer.from(binaryData.data).toString('base64');
            }
        }
        else {
            throw new Error('Unexpected data type: ' + typeof binaryData.data + '. Cannot convert to base64.');
        }
    }

} catch (error) {
    throw new Error('Binary conversion failed: ' + error.message + '. Data type: ' + typeof binaryData.data + ', Has ID: ' + !!binaryData.id);
}

// Validate base64
if (!base64Image) {
    throw new Error('Base64 conversion produced null/undefined result');
}

if (base64Image.length < 100) {
    throw new Error('Base64 too short (' + base64Image.length + ' chars). Expected 10,000+. This indicates conversion failure.');
}

// Create Google Vision API payload
const visionPayload = {
    requests: [{
        image: { 
            content: base64Image 
        },
        features: [{ 
            type: 'TEXT_DETECTION'
        }]
    }]
};

return {
    json: {
        ...item.json,
        vision_payload: visionPayload,
        optimized_file_key: sourceKey,
        processing_note: 'Image processed for OCR',
        base64_length: base64Image.length,
        conversion_method: 'successful'
    },
    binary: item.binary
};

const item = $input.first();
const parsingData = $('Parsing Success?').first().json;
// Extract parsed data
const vendor = (parsingData.vendor || 'Unknown').replace(/[^a-zA-Z0-9]/g, '_');
const currency = parsingData.currency || 'XXX';
const amount = parsingData.total_amount || '0';
const dateStr = parsingData.date || '';
// Format date from DD-MMM-YYYY to DDMMMYYYY
let formattedDate = 'UNKNOWN';
if (dateStr && dateStr !== 'XXX') {
  formattedDate = dateStr.replace(/-/g, '');
}
// Format amount based on currency
const zeroDecimalCurrencies = ['IDR', 'KHR', 'VND', 'JPY', 'KRW', 'CLP', 'PYG'];
let formattedAmount;
if (zeroDecimalCurrencies.includes(currency)) {
  const numAmount = Math.round(parseFloat(amount));
  formattedAmount = numAmount.toLocaleString('en-US');
} else {
  const numAmount = parseFloat(amount);
  formattedAmount = numAmount.toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}
// Build filename
const filename = `${vendor}_${currency}${formattedAmount}_${formattedDate}.jpg`;
// Get binary data from input
const inputBinary = item.binary;
// Construct result with proper binary handling
const result = {
  json: {
    user_id: item.json.user_id,
    chat_id: item.json.chat_id,
    message_id: item.json.message_id,
    dynamic_filename: filename
  }
};
// Add binary data if available
if (inputBinary && inputBinary.data) {
  result.binary = inputBinary;
}
return [result];

const botToken = $input.first().json.bot_token;
const parsingData = $('Parsing Success?').first().json;
const processImageData = $('Process Image').first().json;
const buildFilenameData = $('Build Filename from Parsed Data').first().json;
// Backblaze B2 Configuration
const B2_PUBLIC_URL = 'https://s3.us-east-005.backblazeb2.com/receiptai-images';
// Get user ID and filename
const userId = processImageData.user_id;
const filename = buildFilenameData.dynamic_filename;
// Build B2 file key and public URL
const fileKey = `receipts/${userId}/${filename}`;
const b2Url = `${B2_PUBLIC_URL}/${fileKey}`;
// Merge ALL data
return [{
  json: {
    ...parsingData,
    chat_id: processImageData.chat_id,
    user_id: userId,
    telegram_user_id: processImageData.telegram_user_id,
    storage_provider: 'backblaze-b2',
    drive_file_id: fileKey,
    receipt_image_url: b2Url,
    receipt_direct_url: b2Url,
    file_name: filename,
    bot_token: botToken
  }
}];

// Restore Binary Data - Code Node
// This retrieves the binary data from Prepare OCR Payload and combines it with OCR results

const ocrPayloadItem = $('Prepare OCR Payload').first();
const ocrResult = $input.first().json;

return [{
  json: {
    ...ocrPayloadItem.json,
    ocr_result: ocrResult
  },
  binary: ocrPayloadItem.binary
}];

// Restore Formatted Currency - CONSISTENT FORMATTING (NO SYMBOLS)
const item = $input.first().json;


function formatCurrencyComplete(amount, currencyCode) {
  // Preserve original amount as string
  const amountStr = String(amount);

  const zeroDecimalCurrencies = [
    'BIF', 'CLP', 'DJF', 'GNF', 'ISK', 'JPY', 'KMF', 'KRW', 'PYG', 'RWF', 
    'UGX', 'VND', 'VUV', 'XAF', 'XOF', 'XPF', 'KHR', 'LAK', 'IDR', 'MMK', 'TWD'
  ];

  const isZeroDecimal = zeroDecimalCurrencies.includes(currencyCode);

  if (isZeroDecimal) {
    const numAmount = parseFloat(amountStr.replace(/,/g, ''));
    if (isNaN(numAmount)) {
      return { sheet: '0', raw: amountStr, decimals: 0 };
    }

    // Use exact number formatting without rounding
    const sheetFormat = numAmount.toLocaleString('en-US');
    return { sheet: sheetFormat, raw: amountStr, decimals: 0 };
  } else {
    const numAmount = parseFloat(amountStr.replace(/,/g, ''));
    if (isNaN(numAmount)) {
      return { sheet: '0', raw: amountStr, decimals: 2 };
    }

    const decimalPlaces = (amountStr.split('.')[1] || '').length;
    const decimals = Math.max(decimalPlaces, 2);

    const sheetFormat = numAmount.toLocaleString('en-US', {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals
    });

    return { sheet: sheetFormat, raw: amountStr, decimals: decimals };
  }
}

const currency = item.Currency || item.currency || 'MYR';

// Get the raw amount values from the pending sheet
const rawAmount = item.Amount || item.amount || '0';
const rawTax = item.Tax || item.tax || '0';

// Reformat using consistent function
const amountFormatted = formatCurrencyComplete(rawAmount, currency);
const taxFormatted = formatCurrencyComplete(rawTax, currency);


const result = {
  ...item,
  // Use consistent sheet format for both Sheets AND Telegram
  'Amount': amountFormatted.sheet,
  'Tax': taxFormatted.sheet,
  // Store raw values for calculations
  'amount_raw': amountFormatted.raw,
  'tax_raw': taxFormatted.raw,
  'currency_decimals': amountFormatted.decimals
};


return [{
  json: result
}];

// PDF to Image Converter - SIMPLIFIED WORKING VERSION
const item = $input.first();

// If it's not a PDF, just pass through unchanged
if (!item.json.is_pdf) {
    return [item];
}

if (!item.binary) {
    return [{
        json: {
            ...item.json,
            error: true,
            error_message: 'No binary data available for PDF processing'
        }
    }];
}

const binaryKeys = Object.keys(item.binary);
const fileKey = item.json.file_key;

if (!fileKey || !item.binary[fileKey]) {
    return [{
        json: {
            ...item.json,
            error: true,
            error_message: 'Invalid binary key for PDF processing'
        }
    }];
}

const binaryData = item.binary[fileKey];

try {

    // Use OCR.space API that supports PDF directly
    const ocrSpaceResponse = await $.http.post({
        method: 'POST',
        url: 'https://api.ocr.space/parse/image',
        headers: {
            'apikey': 'K87899142388957' // Free OCR.space API key
        },
        formData: {
            'file': {
                value: binaryData.data,
                options: {
                    filename: item.json.original_filename || 'receipt.pdf',
                    contentType: 'application/pdf'
                }
            },
            'language': 'eng',
            'isOverlayRequired': false,
            'isTable': false,
            'scale': true,
            'OCREngine': 2
        },
        json: true
    });

    if (ocrSpaceResponse && ocrSpaceResponse.ParsedResults && ocrSpaceResponse.ParsedResults[0]) {
        const ocrText = ocrSpaceResponse.ParsedResults[0].ParsedText;


        // Skip the image optimization and go directly to AI parsing
        return [{
            json: {
                ...item.json,
                ocr_text: ocrText,
                processing_note: 'PDF processed via OCR.space API',
                conversion_success: true,
                skip_image_optimization: true,
                skip_google_vision: true // Skip Google Vision since we already have OCR text
            },
            binary: item.binary
        }];
    } else {
        throw new Error('OCR.space API returned no results');
    }

} catch (error) {

    return [{
        json: {
            ...item.json,
            error: true,
            error_message: `PDF processing failed: ${error.message}. Please try with an image file instead.`,
            conversion_success: false
        },
        binary: item.binary
    }];
}

