const item = $input.first();

// ✅ V17 COMPATIBILITY: Respect upstream routing if present
if (item.json.route_to && item.json.route_to !== 'unknown') {
    return [{ json: item.json, binary: item.binary }];
}

// Handle both normalized (from v17) and original Telegram format
const hasCallback = !!(item.json.callback_query || item.json.callback_query_id);
const hasPhoto = !!(item.json.photo || item.json.message?.photo || item.json.is_image);
const hasDocument = !!(item.json.document || item.json.message?.document);
const hasText = !!(item.json.text || item.json.message?.text);

const mimeType = item.json.document?.mime_type || item.json.message?.document?.mime_type;

// Enhanced file format detection
const isImage = item.json.is_image || hasPhoto || (hasDocument && (
    mimeType?.startsWith('image/') || 
    mimeType === 'image/jpeg' ||
    mimeType === 'image/jpg' ||
    mimeType === 'image/png' ||
    mimeType === 'image/heic' ||
    mimeType === 'image/heif'
));

const isPDF = item.json.is_pdf || (hasDocument && (
    mimeType === 'application/pdf' ||
    mimeType === 'application/x-pdf'
));

// Extract chat_id
const chatId = item.json.chat_id || 
               item.json.message?.chat?.id || 
               item.json.callback_query?.message?.chat?.id;

// Handle callback
if (hasCallback) {
    return [{ 
        json: { 
            ...item.json, 
            route_to: 'callback',
            chat_id: chatId
        },
        binary: item.binary
    }];
}

// Handle images/PDFs
if (isImage || isPDF) {
    return [{ 
        json: { 
            ...item.json, 
            route_to: 'image', 
            is_pdf: isPDF,
            chat_id: chatId
        },
        binary: item.binary
    }];
}

// Handle text messages
if (hasText) {
    const messageText = item.json.text || item.json.message?.text || '';
    const isReplyToBot = !!(item.json.message?.reply_to_message);
    const replyText = item.json.message?.reply_to_message?.text || '';
    const isBotAsking = replyText.includes('Would you like:') || 
                       replyText.includes('I can help!') ||
                       replyText.includes('1)') ||
                       replyText.includes('2)') ||
                       replyText.includes('3)');

    // Question word detection
    const questionWords = ['what', 'how', 'why', 'when', 'where', 'who', 'which', 
                           'can you', 'could you', 'tell me', 'show me', 'give me', 
                           'summarize', 'analyze', 'explain', 'list', 'find'];

    // Command pattern detection
    const fixCommandPatterns = [
        /^fix$/i, /^update$/i, /^correct$/i, /^change$/i, /^edit$/i
    ];

    const isNumericOnly = /^\d+$/.test(messageText.trim());
    const isShortText = messageText.trim().length <= 3;
    const questionMarks = (messageText.match(/\?/g) || []).length;
    const textLower = messageText.toLowerCase().trim();
    const wordCount = messageText.trim().split(/\s+/).length;

    const hasQuestionWord = questionWords.some(word => textLower.includes(word));
    const hasQuestionMark = questionMarks > 0;
    const isLongText = wordCount > 5;
    const isFixCommand = fixCommandPatterns.some(pattern => pattern.test(messageText.trim()));

    let routeDestination = 'text_fix';

    if (isReplyToBot && isBotAsking) {
        routeDestination = 'ai_query';
    }
    else if ((isNumericOnly || isShortText) && !isFixCommand) {
        routeDestination = 'ai_query';
    }
    else if ((hasQuestionWord || hasQuestionMark) && !isFixCommand) {
        routeDestination = 'ai_query';
    }
    else if (isLongText && !isFixCommand) {
        routeDestination = 'ai_query';
    }
    else if (isFixCommand) {
        routeDestination = 'text_fix';
    }


    return [{ 
        json: { 
            ...item.json, 
            route_to: routeDestination,
            message_text: messageText,
            chat_id: chatId,
            classification_metadata: {
                word_count: wordCount,
                has_question_word: hasQuestionWord,
                has_question_mark: hasQuestionMark,
                is_fix_command: isFixCommand,
                is_reply_to_bot: isReplyToBot,
                is_numeric_only: isNumericOnly,
                routing_decision: routeDestination
            }
        },
        binary: item.binary
    }];
}

return [{ 
    json: { 
        ...item.json, 
        route_to: 'unknown',
        chat_id: chatId
    },
    binary: item.binary
}];

