SELECT 
  COALESCE(
    (SELECT row_to_json(t)
     FROM (
         SELECT etp.*, u.telegram_bot_token as bot_token, u.id as user_id FROM expense_tracker_pending etp
LEFT JOIN users u ON u.telegram_chat_id::text = etp.chat_id::text
         WHERE chat_id = {{ $json.verified_user.telegram_user_id }}
         ORDER BY created_at DESC
         LIMIT 1
     ) t
  ),
  NULL
) as pending_record;

