const item = $input.first().json;
let text = item.text || item.output || '';


// Fix common Markdown issues
text = text
  // Remove lone brackets that aren't part of valid Markdown links
  .replace(/\[(?![^\]]*\]\([^)]*\))/g, '')  // Remove [ without matching ](url)
  .replace(/(?<!\[[^\]]*)\]/g, '')  // Remove ] without matching [text

  // Fix broken bold/italic markers
  .replace(/\*\*([^*]*)\*(?!\*)/g, '**$1**')  // Fix ** without closing **
  .replace(/\*(?!\*)([^*]*)\*\*/g, '*$1*')    // Fix * without closing *

  // Escape special Telegram Markdown characters if not part of valid syntax
  .replace(/(?<!\\)_(?![^_]*_)/g, '\\_')  // Escape lone underscores

  // Remove standalone # if not part of header
  .replace(/\n#(?!\s)/g, '\n')

  // Clean up excessive newlines (max 2 consecutive)
  .replace(/\n{3,}/g, '\n\n');


return [{
  json: {
    ...item,
    text: text
  }
}];

