// DETERMINISTIC QUERY INTENT CLASSIFIER v7.2
// IMPROVED: Full database field support, submitted_at detection, location/payment extraction
// FIXED: Pass through bot_token for invalid query handling
const items = $input.all();
    // Helper: Levenshtein distance for fuzzy matching
const results = [];
for (const item of items) {
    const messageText = (item.json.message_text || item.json.text || '').toLowerCase().trim();
    const originalMessage = item.json.message_text || item.json.text || '';
    const chatId = item.json.chat_id;
    const botToken = item.json.bot_token;
    const classification = {
        session_id: 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) { const r = Math.random()*16|0; return c === 'x' ? r.toString(16) : (r & 0x3 | 0x8).toString(16); }),
        chat_id: chatId,
        bot_token: botToken,
        message_text: item.json.message_text || item.json.text,
        query_type: 'unknown',
        date_field: 'expense_date',
        filters: {
            date_from: null,
            date_to: null,
            category: null,
            location: null,
            vendor: null,
            amount_filter: null,
            payment_method: null
        },
        sort: null,
        limit: null,
        confidence: 0,
        needs_clarification: false,
        clarification_message: null,
        is_valid_expense_query: true,
        invalid_query_message: null
    };
    // Known locations for fuzzy matching
    const knownLocations = [
        "singapore", "malaysia", "thailand", "cambodia", "indonesia", "vietnam", "philippines",
        "japan", "korea", "china", "taiwan", "hong kong", "india", "australia", "usa", "united states",
        "united kingdom", "uk", "germany", "france", "italy", "spain", "netherlands", "switzerland",
        "kuala lumpur", "petaling jaya", "puchong", "johor", "penang", "bangkok", "phnom penh",
        "jakarta", "manila", "tokyo", "seoul", "shanghai", "beijing", "hanoi", "ho chi minh",
        "sydney", "melbourne", "london", "new york", "los angeles", "san francisco"
    ];

    // Levenshtein distance helper
    function levenshteinDistance(s1, s2) {
        if (s1.length < s2.length) return levenshteinDistance(s2, s1);
        if (s2.length === 0) return s1.length;
        let previousRow = Array.from({length: s2.length + 1}, (_, i) => i);
        for (let i = 0; i < s1.length; i++) {
            let currentRow = [i + 1];
            for (let j = 0; j < s2.length; j++) {
                let insertions = previousRow[j + 1] + 1;
                let deletions = currentRow[j] + 1;
                let substitutions = previousRow[j] + (s1[i] !== s2[j]);
                currentRow.push(Math.min(insertions, deletions, substitutions));
            }
            previousRow = currentRow;
        }
        return previousRow[previousRow.length - 1];
    }
    // 0. QUERY VALIDATION - Check if query is expense-related (NEW in v6.0)
    const expenseKeywords = ['expense', 'expenses', 'receipt', 'receipts', 'transaction', 'transactions', 'spending', 'spent', 'cost', 'costs', 'paid', 'pay', 'payment', 'purchase', 'purchases', 'bought', 'buy', 'money', 'amount', 'total', 'sum', 'breakdown', 'summary', 'list', 'show', 'display', 'how many', 'how much', 'count', 'average', 'highest', 'lowest', 'cheapest', 'expensive', 'today', 'yesterday', 'this week', 'this month', 'last month', 'breakfast', 'lunch', 'dinner', 'meal', 'meals', 'food', 'transport', 'transportation', 'flight', 'groceries', 'shopping', 'category', 'vendor', 'sgd', 'myr', 'usd', 'thb'];
    const hasExpenseKeyword = expenseKeywords.some(keyword => messageText.includes(keyword));
    // Check for very short or nonsense queries
    const isTooShort = messageText.length < 3;
    const isJustPunctuation = /^[?!.,;:]+$/.test(messageText);
    const isGreeting = /^(hi|hello|hey|yo|sup|greetings|good\s*(morning|afternoon|evening))\s*[!?.,]*$/i.test(messageText);
    const isGibberish = /^(what|huh|eh|um|hmm|ok|okay|yes|no|yeah|nope|nah|lol|haha|wow|omg|wtf|idk|brb)\s*[?!.,]*$/i.test(messageText);
    const isQuestion = /^(do you|can you|are you|will you|would you|could you|should|what is|who is|where is|why|how do)\s+(understand|know|help|work|do)/i.test(messageText);
    const isCommand = /^(view|open|click|tap|see|look|watch|read|check)\s*(receipt|image|photo|picture|file|link|url)?\s*[?!.,]*$/i.test(messageText);
    const isOffTopic = /^(weather|news|joke|story|song|music|game|play|cook|recipe|movie|sport|football|soccer)/i.test(messageText);
    if (isTooShort || isJustPunctuation || isGreeting || isGibberish || isQuestion || isCommand || isOffTopic || !hasExpenseKeyword) {
        classification.is_valid_expense_query = false;
        classification.invalid_query_message = '🤖 I\'m your **Expense Tracking Assistant**!\n\nI can only help with questions about your expenses and receipts. Here are some things you can ask me:\n\n📋 **View expenses:**\n• "Show me my expenses today"\n• "List all meal expenses"\n• "What did I spend this month?"\n\n🔍 **Search & filter:**\n• "Show me Firstcoach receipts"\n• "Find expenses over SGD 50"\n• "List my dinner expenses"\n\n📊 **Summaries:**\n• "What\'s my total spending?"\n• "Give me a breakdown by category"\n• "What\'s my most expensive receipt?"\n\n💡 Try one of these commands to get started!';
        results.push({ json: classification });
        continue;
    }
    // 1. AMOUNT FILTER EXTRACTION (More tolerant regex)
    const amountMatch = messageText.match(/(?:over|above|more than|greater than|higher than)\s*(?:sgd|myr|thb|\$)?\s*(\d+(?:\.\d+)?)/i);
    const amountBelowMatch = messageText.match(/(?:under|below|less than|lower than)\s*(?:sgd|myr|thb|\$)?\s*(\d+(?:\.\d+)?)/i);
    if (amountMatch) {
        classification.filters.amount_filter = { operator: '>', value: parseFloat(amountMatch[1]) };
    } else if (amountBelowMatch) {
        classification.filters.amount_filter = { operator: '<', value: parseFloat(amountBelowMatch[1]) };
    }
    // 2. LIMIT EXTRACTION
    const limitPatterns = [
        /\b(?:top|first|last|lowest|highest|cheapest|bottom)\s+(\d+)\b/i,
        /\b(\d+)\s+(?:top|first|last|lowest|highest|cheapest|bottom)\b/i
    ];
    for (const pattern of limitPatterns) {
        const match = messageText.match(pattern);
        if (match) {
            const digits = match[1] || match[2];
            if (digits) classification.limit = parseInt(digits);
            break;
        }
    }
    // 3. QUERY TYPE DETECTION
    if (/\b(range|earliest|latest|first|last|oldest|newest).{0,50}\b(date|time|when)s?\b/i.test(messageText)) {
        classification.query_type = 'summary';
        classification.confidence = 95;
    }
    else if (/\b(how many|count|number of|total (count|number)|how much)\b/i.test(messageText)) {
        classification.query_type = 'count';
        classification.confidence = 95;
    }
    else if (/\b(list|show (all|me)|display|give me).*\b(expense|receipt|transaction)s?\b/i.test(messageText)) {
        classification.query_type = 'list';
        classification.confidence = 90;
    }
    else if (/\b(details?|info|information|tell me about|what (are|were))\b/i.test(messageText)) {
        classification.query_type = 'details';
        classification.confidence = 85;
    }
    else if (/\b(summar(y|ize)|total|breakdown|group by|average|spending habit)\b/i.test(messageText) ||
        /\b(most expensive|cheapest|lowest|highest)\b/i.test(messageText)) {
        classification.query_type = 'summary';
        classification.confidence = 90;
    }
    if (classification.query_type === 'unknown') {
        classification.query_type = 'list';
        classification.confidence = 50;
    }
    // 4. SORT ORDER
    if (/\b(most expensive|highest|largest|biggest)\b/i.test(messageText)) {
        classification.sort = 'amount_desc';
        if (!classification.limit) classification.limit = 1;
    }
    else if (/\b(cheapest|lowest|smallest)\b/i.test(messageText)) {
        classification.sort = 'amount_asc';
        if (!classification.limit) classification.limit = 1;
    }
    // 5. DATE FIELD DETECTION (expense_date vs submitted_at)
    // If user mentions "submitted", use submitted_at field instead of expense_date
    if (/\b(submitted|upload|sent|added)\b/i.test(messageText)) {
        classification.date_field = 'submitted_at';
    }
    // 5b. DATE FILTERS
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    if (/\btoday\b/i.test(messageText)) {
        const s = today.toISOString().split('T')[0];
        classification.filters.date_from = s; classification.filters.date_to = s;
    }
    else if (/\byesterday\b/i.test(messageText)) {
        const y = new Date(today); y.setDate(y.getDate() - 1);
        const s = y.toISOString().split('T')[0];
        classification.filters.date_from = s; classification.filters.date_to = s;
    }
    else if (/\b(this\s+week|current\s+week)\b/i.test(messageText)) {
        const dayOfWeek = today.getDay();
        const startOfWeek = new Date(today);
        startOfWeek.setDate(today.getDate() - dayOfWeek);
        classification.filters.date_from = startOfWeek.toISOString().split('T')[0];
        classification.filters.date_to = today.toISOString().split('T')[0];
    }
    else if (/\b(last\s+week|previous\s+week)\b/i.test(messageText)) {
