// Shuffle providers for load balancing
function shuffleArray(array) {
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

const shuffledProviders = shuffleArray(API_PROVIDERS);

// PREMIUM AI DASHBOARD PROMPT v6.0
// Focus: Anti-Hallucination, Vendor Filtering, Self-Verification
const CURRENT_DATE = new Date().toLocaleDateString('en-SG', {
    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Singapore'
});
// Extract vendor filter if present for strict filtering
const vendorFilter = filters.vendor ? filters.vendor.toLowerCase() : null;
const AI_PROMPT_CONFIG = {
    system_instruction: `You are a High-End Financial Assistant. Format expense data into a "Premium Financial Dashboard" style for Telegram.

CURRENT DATE: ${CURRENT_DATE}
${vendorFilter ? `VENDOR FILTER ACTIVE: "${vendorFilter}" - ONLY include records where vendor contains this name!` : ''}

⚠️ CRITICAL ANTI-HALLUCINATION RULES (MANDATORY):
1. You MUST ONLY use data that appears EXACTLY in the SQL RESULTS below
2. NEVER invent, assume, or add any vendor names not in the data
3. NEVER add any amounts not present in the SQL RESULTS
4. If SQL RESULTS is empty or has 0 records, respond: "No expenses found matching your criteria 🕳️"
5. Count of items in your response MUST EQUAL count of items in SQL RESULTS
6. ${vendorFilter ? `STRICT VENDOR FILTER: Only include records where vendor field contains "${vendorFilter}"` : 'Include all records from SQL RESULTS'}

📋 SELF-VERIFICATION CHECKLIST (Do this before responding):
✓ Every vendor name I mention exists in SQL RESULTS
✓ Every amount I mention exists in SQL RESULTS
✓ Number of transactions listed = Number of records in SQL RESULTS
✓ I have NOT added any extra items
✓ ${vendorFilter ? `All items match the vendor filter "${vendorFilter}"` : 'No vendor filter applied'}

If you cannot verify ALL checkpoints, use simple format:
"📋 [X] expenses found:\n1. [Vendor] - [Amount]\n..."`,
    formatting_guidelines: `
LAYOUT STRUCTURE:
1️⃣ HEADER:
- Start with: "✨ Financial Overview: [Period]"
- Total line: "💰 *SGD [Amount]*" (sum of amount_sgd from SQL RESULTS only)
2️⃣ SUMMARY METRICS:
- "📊 Avg: SGD [X] | 📈 Max: SGD [Y]" (calculate from SQL RESULTS only)
3️⃣ CATEGORY BREAKDOWN:
- Icons: 🍴 Meals, ✈️ Transportation, 🛍️ Shopping, 🛒 Groceries, 🎬 Entertainment, 🏥 Medical, 🏷️ Other
- Format: "✈️ *Transportation*: SGD [sum] ([count] receipts) 🟦🟦⬜⬜⬜"
4️⃣ TRANSACTION LIST (from SQL RESULTS only):
[1]. *[vendor from SQL]*
└─ [currency] [amount_original] · [category] · 📅 [expense_date]
📎 [View Receipt](receipt_image_url) - use Markdown hyperlink format, NOT the full URL
5️⃣ INSIGHT (based on actual data only):
"💡 *Strategic Insight:* [observation from actual spending patterns]"

Rules:
- Use *bold* for emphasis
- Max 4000 characters
- For lists > 10: "—— 📄 *Showing 10 of [Total] transactions* ——"
- IMPORTANT: Format receipt links as Markdown hyperlinks: 📎 [View Receipt](URL)
- NEVER show the full URL - always use [View Receipt](URL) format`
};

// Integration snippet for Simple Formatter:
const PROMPT = `${AI_PROMPT_CONFIG.system_instruction}\n\n` +
    `Query: "${messageText}"\n` +
    `Metadata: Type=${queryType}\n\n` +
    `SQL RESULTS:\n${JSON.stringify(cleanResults, null, 2)}\n\n` +
    `${AI_PROMPT_CONFIG.formatting_guidelines}\n\n` +
    `Return the formatted dashboard now:`;

// Provider processing function
async function tryProvider(provider, prompt) {
  try {
    const startTime = Date.now();
    const config = provider.config(prompt);
    const response = await this.helpers.httpRequest(config);
    const elapsed = ((Date.now() - startTime) / 1000).toFixed(2);

    let content;
    if (provider.name.includes('Gemini')) {
      content = response.candidates?.[0]?.content?.parts?.[0]?.text;
    } else if (provider.name.includes('Anthropic')) {
      content = response.content?.[0]?.text;
    } else {
      content = response.choices?.[0]?.message?.content;
    }

    if (!content) throw new Error('Empty response');


    return {
      success: true,
      output: content.trim(),
      provider: provider.name,
      elapsed: parseFloat(elapsed)
    };

  } catch (error) {
    return { success: false };
  }
}

// Try providers with failover
let result;
for (const provider of shuffledProviders) {
  result = await tryProvider.call(this, provider, PROMPT);

  if (result.success) {
    break;
  }
}

// SAFE FORMATTER FUNCTION v3.1
// Generates verified output directly from SQL results with Markdown hyperlinks
function generateSafeOutput(results, qType, vFilter) {
  let output = '';
  if (qType === 'count') {
    const count = results[0]?.total_count || 0;
    output = `🔢 Found **${count}** expense${count !== 1 ? 's' : ''}`;
  } else if (qType === 'list' || qType === 'details') {
    const total = results.reduce((sum, r) => sum + parseFloat(r.amount_sgd || 0), 0);
    output = `📋 **Your Expenses** (${results.length} items)\n💰 Total: **SGD ${total.toFixed(2)}**\n\n`;
    results.forEach((row, idx) => {
      output += `${idx + 1}. **${row.vendor}**\n`;
      output += `   └─ ${row.currency || 'SGD'} ${parseFloat(row.amount_original || row.amount_sgd).toFixed(2)} · ${row.category || 'Uncategorized'} · 📅 ${row.expense_date}\n`;
      if (row.receipt_image_url) {
        output += `   📎 [View Receipt](${row.receipt_image_url})\n`;
      }
    });
  } else {
    output = `Found ${results.length} results.`;
  }
  return output;
}

// Fallback to simple formatting if all AI providers fail
if (!result || !result.success) {
  const output = generateSafeOutput(cleanResults, queryType, vendorFilter);
  return [{
    json: {
      session_id: sessionId, chat_id: chatId,
      output: output,
      query_type: queryType,
      formatted_by: 'fallback',
      verified: true
    ,
    bot_token: botToken}
  }];
}

// RESPONSE VERIFICATION v1.0
// Check AI output for hallucinations before returning
const actualVendors = cleanResults.map(r => (r.vendor || '').toLowerCase());
const aiOutput = result.output;
let hallucinated = false;
let hallucinatedItems = [];

// Extract vendor mentions from AI output (look for numbered list patterns)
const vendorMentions = aiOutput.match(/\d+\.\s*\*?\*?([^\n*└─·]+)/g) || [];
for (const mention of vendorMentions) {
  const cleanMention = mention.replace(/^\d+\.\s*\*?\*?/, '').trim().toLowerCase().split('*')[0].trim();
  if (cleanMention.length > 2) {
    const matchFound = actualVendors.some(v => 
      v && (cleanMention.includes(v) || v.includes(cleanMention.split(' ')[0]))
    );
    if (!matchFound && !cleanMention.match(/^(sgd|myr|thb|usd|\d|total|avg|max|min)/i)) {
      hallucinated = true;
      hallucinatedItems.push(cleanMention);
    }
  }
}

// If hallucination detected, use safe formatter instead
if (hallucinated && hallucinatedItems.length > 0) {
  const safeOutput = generateSafeOutput(cleanResults, queryType, vendorFilter);
  return [{
    json: {
      session_id: sessionId, chat_id: chatId,
      output: safeOutput + `\n\n⚠️ _Response verified for accuracy_`,
      query_type: queryType,
      formatted_by: 'verified_fallback',
      hallucination_detected: true,
      flagged_items: hallucinatedItems,
      verified: true
    ,
    bot_token: botToken}
  }];
}

// Return AI-formatted result (passed verification)
return [{
  json: {
    session_id: sessionId, chat_id: chatId,
    output: result.output,
    query_type: queryType,
    formatted_by: result.provider,
    formatting_time: result.elapsed,
    verified: true
  ,
    bot_token: botToken}
}];

