const item = $input.first().json;

// Helper function for formatting amounts
function formatAmount(amount, currency) {
  const zeroDecimalCurrencies = ['IDR', 'KHR', 'VND', 'JPY', 'KRW'];
  const num = parseFloat(amount || 0);

  if (zeroDecimalCurrencies.includes(currency)) {
    return Math.round(num).toLocaleString('en-US');
  } else {
    return num.toLocaleString('en-US', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
  }
}

// Build the message text
const text = `⚠️ The following ❌ fields need your attention

Date: ${item.date === 'XXX' ? '❌ UNKNOWN' : item.date}
Time: ${item.time === 'XXX' ? '❌ UNKNOWN' : item.time}
Vendor: ${item.vendor === 'XXX' ? '❌ UNKNOWN' : item.vendor}
Location: ${item.location === 'XXX' ? '❌ UNKNOWN' : item.location}
Total: ${item.currency === 'XXX' ? '❌' : item.currency} ${item.amount === '0.00' ? '❌ UNKNOWN' : formatAmount(item.amount, item.currency)}
Tax: ${item.currency === 'XXX' ? '❌' : item.currency} ${formatAmount(item.tax || item.Tax || 0, item.currency)}
Category: ${item.category}
Confidence Score: ${item.confidence_score}% ${(item.confidence_score || 0) < 75 ? '⚠️' : '✅'}
Comment: ${item.comment}

View Receipt Image

👇 Fix These Missing Fields 👇`;

