const item = $input.first();
const binary = item.binary;
const keys = Object.keys(binary);
if (keys.length === 0) {
  return [{ json: { error: 'No binary data' }}];
}
const key = keys[0];
const binaryData = binary[key];
// Return both JSON and binary
return [{
  json: {
    ...item.json,
    binaryKey: key,
    mimeType: binaryData.mimeType,
    fileName: binaryData.fileName
  },
  binary: binary
}];

